import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';

import 'firebase_options.dart';
import 'screens/auth_gate.dart';
import 'theme.dart';

Future<void> main() async {
  // Flutter bindings must exist before any plugin (Firebase) is called.
  WidgetsFlutterBinding.ensureInitialized();

  try {
    // Firebase is initialized BEFORE runApp() using the platform options
    // generated by `flutterfire configure`.
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (_) {
    // Show a friendly screen instead of crashing on a bad/missing config.
    runApp(const _FirebaseInitErrorApp());
    return;
  }

  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'ICA13 Firebase Auth',
      debugShowCheckedModeBanner: false,
      theme: buildAppTheme(),
      // AuthGate listens to Firebase auth state and decides which screen
      // (signed-in profile vs. sign-in/register) is shown.
      home: const AuthGate(),
    );
  }
}

class _FirebaseInitErrorApp extends StatelessWidget {
  const _FirebaseInitErrorApp();

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      theme: buildAppTheme(),
      home: const Scaffold(
        body: Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text(
              'The app could not connect to Firebase.\n'
              'Check your connection and restart the app.',
              textAlign: TextAlign.center,
            ),
          ),
        ),
      ),
    );
  }
}
